mapper.select:
SELECT a.operation_id,a.upload_id,b.file_operation_id,a.failure_code FROM pf.workspace_tool_file_admission a
LEFT JOIN pf.workspace_tool_job_binding b ON b.operation_id=a.operation_id AND b.file_operation_id IS NOT NULL
WHERE a.operation_id=#{operation}

mapper.insert:
INSERT INTO pf.workspace_tool_file_admission(operation_id,space_id,task_id,workspace_id,attempt_id,owner_id,generation,fence,upload_id,failure_code)
SELECT i.operation_id,i.space_id,i.task_id,i.workspace_id,#{lease.attemptId},#{lease.ownerId},d.generation,#{lease.fence},#{upload,jdbcType=OTHER},#{failure,jdbcType=VARCHAR}
FROM pf.workspace_tool_intent i JOIN pf.execution_dispatch d ON d.task_id=i.task_id
JOIN pf.tool_operation o ON o.id=i.operation_id AND o.status='RUNNING'
WHERE i.operation_id=#{operation} AND i.space_id=#{lease.spaceId} AND i.task_id=#{lease.taskId}
  AND i.tool_name='workspace_write' AND d.status='CLAIMED' AND d.lease_owner=#{lease.ownerId} AND d.fencing_token=#{lease.fence}
  AND (CAST(#{upload,jdbcType=OTHER} AS uuid) IS NULL OR EXISTS(SELECT 1 FROM pf.upload_session u WHERE u.id=#{upload,jdbcType=OTHER}
    AND u.space_id=i.space_id AND u.workspace_id=i.workspace_id AND u.actor_id=i.actor_id AND u.request_id=i.operation_id))

mapper.select:
SELECT jsonb_build_object('fileId',f.id,'path',f.relative_path,'kind',f.kind,'revision',f.revision,
  'currentVersionId',f.current_version_id,'versionId',v.id,'sha256',v.sha256,'bytes',v.size_bytes)::text
FROM pf.file_entry f LEFT JOIN pf.file_version v ON v.space_id=f.space_id AND v.workspace_id=f.workspace_id AND v.file_id=f.id AND v.id=#{version}
WHERE f.space_id=#{space} AND f.workspace_id=#{workspace} AND f.id=#{file}

SELECT jsonb_build_object('fileId',id,'path',relative_path,'kind',kind,'revision',revision,
  'currentVersionId',current_version_id,'collectionState',collection_state)::text FROM pf.file_entry
WHERE space_id=#{space} AND workspace_id=#{workspace} AND relative_path=#{path}
